#!/usr/bin/env node
'use strict';
/**
 * tools/z32search_grammar_member.js - is a phrase generated by the z32search radian/inch grammar, and
 * does it fit Z32?  Parses the letters against every grammar form (tools/z32search_grammar_lib.js).
 *   node tools/z32search_grammar_member.js -> results/z32search/grammar/published_membership.json
 */
const fs = require('fs');
const path = require('path');
const G = require('./z32search_grammar_lib');
const E = require('./z32search_grammar_count');
const Z = require('./z32search_lib');

const F = E.prepForms(G.forms());
function parses(target) {
  const out = [];
  for (const f of F) {
    const rec = (si, off, toks) => {
      if (si === f.slots.length) { if (off === target.length) out.push({ form: f.id, tokens: toks.filter(Boolean).join(' ') }); return; }
      for (const s of f.slots[si].strings) if (target.startsWith(s, off)) rec(si + 1, off + s.length, [...toks, s]);
    };
    rec(0, 0, []);
  }
  return out;
}
const pub = {
  'Grinell 2020 / InStepWithTheStars': 'ESTIMATE FOUR RADIANS AND FIVE INCHES',
  'DMW 2019 / Stampher 2026': 'IN THREE AND THREE EIGHTHS RADIANS TEN',
  'Cragle 2022': 'THREE RADIANS FROM MOUNT AREA TWO INCH',
  'Foxon 2023 candidate (needs his transposition)': 'TWELVE INCHES ALONG THE THREE RADIANS',
};
const pairs = Z.pairsOf(Z.z32Text('canonical'));
const res = {};
for (const [who, p] of Object.entries(pub)) {
  const s = G.letters(p);
  const ps = parses(s);
  res[who] = { text: p, length: s.length, fitsZ32: s.length === 32 && Z.satisfies(s, pairs), generatedByGrammar: ps.length > 0, parses: ps.slice(0, 5) };
}
const out = path.join(Z.ROOT, 'results', 'z32search', 'grammar', 'published_membership.json');
fs.writeFileSync(out, JSON.stringify(res, null, 1));
console.log(JSON.stringify(res, null, 1));
